/**
 * Downloads the Research & Planning report generated by the backend from PERSISTED data
 * (GET /runs/{id}/report), so an export never reflects stale browser state. The file is checked
 * before it is offered: success is only reported for a file that really exists and is well formed.
 */
import { apiUrl } from "@/lib/api/client";
import { ENDPOINTS } from "@/lib/api/endpoints";
import { downloadBlob } from "./graph-export";

export type ReportFormat = "md" | "json" | "pdf";

export async function downloadReport(runId: string, format: ReportFormat): Promise<string> {
  let res: Response;
  try {
    res = await fetch(apiUrl(ENDPOINTS.report, { id: runId }, { format }), { credentials: "include" });
  } catch {
    throw new Error("Couldn't reach the server to build the report.");
  }
  if (res.status === 401 || res.status === 403) throw new Error("You don't have access to this report. Sign in again.");
  if (res.status === 404) throw new Error("This run has no report yet.");
  if (!res.ok) throw new Error("The report could not be generated right now. Try again in a moment.");
  const blob = await res.blob();
  if (blob.size === 0) throw new Error("The server returned an empty report.");
  const head = new Uint8Array(await blob.slice(0, 5).arrayBuffer());
  if (format === "pdf" && String.fromCharCode(...head) !== "%PDF-") throw new Error("The server did not return a valid PDF.");
  const cd = res.headers.get("content-disposition") ?? "";
  const name = /filename="?([^";]+)"?/i.exec(cd)?.[1] ?? `research-report-run-${runId}.${format}`;
  downloadBlob(blob, name);
  return name;
}
